#include "stdlib/blas/ext/base/ndarray/dcusumkbn.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>

int main( void ) {
	// Create data buffers:
	const double dataX[] = { 1.0e16, 1.0, -1.0e16 };
	double dataY[] = { 0.0, 0.0, 0.0 };
	const double dataInitial[] = { 123.0, 0.0 };

	// Specify the ndarray metadata:
	int64_t shape[] = { 3 };
	int64_t strides[] = { STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT };
	int64_t scalarStrides[] = { 0 };
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR };
	const enum STDLIB_NDARRAY_ORDER order = STDLIB_NDARRAY_ROW_MAJOR;
	const enum STDLIB_NDARRAY_INDEX_MODE imode = STDLIB_NDARRAY_INDEX_ERROR;

	// Create one-dimensional input and output ndarrays:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *x = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataX, 1, shape, strides, 0, order, imode, 1, submodes );
	// cppcheck-suppress invalidPointerCast
	struct ndarray *y = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataY, 1, shape, strides, 0, order, imode, 1, submodes );

	// Select an initial sum of zero at the scalar's own byte offset:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *initial = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataInitial, 0, NULL, scalarStrides, STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT, order, imode, 1, submodes );
	int status = EXIT_SUCCESS;
	if ( x == NULL || y == NULL || initial == NULL ) {
		fprintf( stderr, "Error allocating ndarray descriptors.\n" );
		status = EXIT_FAILURE;
	} else {
		const struct ndarray *arrays[] = { x, y, initial };
		stdlib_blas_ext_dcusumkbn( arrays );

		// Compensated summation retains the unit term after cancellation:
		if ( dataY[ 0 ] != 1.0e16 || dataY[ 1 ] != 1.0e16 || dataY[ 2 ] != 1.0 ) {
			fprintf( stderr, "Unexpected cumulative sum.\n" );
			status = EXIT_FAILURE;
		}
		for ( int i = 0; i < 3; i++ ) {
			printf( "y[ %i ] = %.17g\n", i, dataY[ i ] );
		}
	}

	// Free any successfully allocated descriptors:
	if ( x != NULL ) {
		stdlib_ndarray_free( x );
	}
	if ( y != NULL ) {
		stdlib_ndarray_free( y );
	}
	if ( initial != NULL ) {
		stdlib_ndarray_free( initial );
	}
	return status;
}
